try.code:
for text in ["12", "abc", "0"]:
    try:
        n = int(text)
        print(12 / n)
    except ValueError:
        print(text, "不是數字！")
    except ZeroDivisionError:
        print("不能除以 0！")
    finally:
        print("--")

