bubble.code:
data = [3, 5, 2, 1]
n = len(data)
for i in range(n - 1):
    for j in range(n - 1 - i):
        if data[j] > data[j + 1]:
            data[j], data[j + 1] = data[j + 1], data[j]
    print("第", i + 1, "輪：", data)

